describe('Notification Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', '**/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          {
            id: '1',
            title: 'New Message',
            message: 'You have a new message from John',
            type: 'message',
            read: false,
            relatedContentId: 'msg-123',
            relatedContentUrl: '/messages/msg-123',
            timestamp: new Date().toISOString()
          },
          {
            id: '2',
            title: 'Comment Reply',
            message: 'Someone replied to your comment',
            type: 'comment',
            read: false,
            relatedContentId: 'post-456',
            relatedContentUrl: '/posts/post-456',
            timestamp: new Date().toISOString()
          }
        ]
      }
    }).as('getNotifications');

    cy.intercept('GET', '**/api/notifications/1/mark-read', {
      statusCode: 200,
      body: { success: true }
    }).as('markNotificationRead');

    cy.intercept('GET', '**/messages/msg-123', {
      statusCode: 200,
      body: { id: 'msg-123', content: 'Test message content' }
    }).as('getMessageContent');
  });

  it('should navigate to related content when clicking a notification', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.wait('@getNotifications');

    cy.get('[data-testid="notification-item-1"]').should('be.visible');
    cy.get('[data-testid="notification-item-1"]').should('contain', 'New Message');
    cy.get('[data-testid="notification-item-1"]').should('contain', 'You have a new message from John');

    cy.get('[data-testid="notification-item-1"]').click();
    cy.wait('@markNotificationRead');
    cy.wait('@getMessageContent');

    cy.url().should('include', '/messages/msg-123');
    cy.get('[data-testid="message-content"]').should('contain', 'Test message content');
    cy.get('[data-testid="notification-item-1"]').should('have.class', 'read');
  });

  it('should handle multiple notifications and navigate to correct content', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.wait('@getNotifications');

    cy.get('[data-testid="notification-item-2"]').should('be.visible');
    cy.get('[data-testid="notification-item-2"]').should('contain', 'Comment Reply');

    cy.intercept('GET', '**/api/notifications/2/mark-read', {
      statusCode: 200,
      body: { success: true }
    }).as('markNotification2Read');

    cy.intercept('GET', '**/posts/post-456', {
      statusCode: 200,
      body: { id: 'post-456', title: 'Test Post', comments: [] }
    }).as('getPostContent');

    cy.get('[data-testid="notification-item-2"]').click();
    cy.wait('@markNotification2Read');
    cy.wait('@getPostContent');

    cy.url().should('include', '/posts/post-456');
    cy.get('[data-testid="post-title"]').should('contain', 'Test Post');
  });

  it('should handle notification click with missing related content gracefully', () => {
    cy.intercept('GET', '**/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          {
            id: '3',
            title: 'Deleted Content',
            message: 'The content you were notified about has been deleted',
            type: 'deleted',
            read: false,
            relatedContentId: null,
            relatedContentUrl: null,
            timestamp: new Date().toISOString()
          }
        ]
      }
    }).as('getNotificationsWithMissing');

    cy.get('[data-testid="notification-bell"]').click();
    cy.wait('@getNotificationsWithMissing');

    cy.get('[data-testid="notification-item-3"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Content no longer available');
    cy.url().should('not.include', '/messages');
    cy.url().should('not.include', '/posts');
  });

  it('should close notification panel after navigation', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.wait('@getNotifications');

    cy.get('[data-testid="notification-panel"]').should('be.visible');
    cy.get('[data-testid="notification-item-1"]').click();
    cy.wait('@markNotificationRead');
    cy.wait('@getMessageContent');

    cy.get('[data-testid="notification-panel"]').should('not.be.visible');
  });

  it('should maintain notification state across page navigation', () => {
    cy.get('[data-testid="notification-bell"]').click();
    cy.wait('@getNotifications');

    cy.get('[data-testid="notification-item-1"]').should('have.attr', 'data-read', 'false');
    cy.get('[data-testid="notification-item-1"]').click();
    cy.wait('@markNotificationRead');
    cy.wait('@getMessageContent');

    cy.go('back');
    cy.get('[data-testid="notification-bell"]').click();
    cy.get('[data-testid="notification-item-1"]').should('have.class', 'read');
  });
});
